create or replace function public.enforce_team_hq_project_limit()
returns trigger language plpgsql security definer set search_path=public as $$
declare active_count integer;
begin
 if new.status not in ('queued','in_progress') then return new; end if;
 perform 1 from public.teams where id=new.team_id for update;
 select count(*) into active_count from public.caleris_team_hq_projects p where p.team_id=new.team_id and p.status in ('queued','in_progress') and p.id <> coalesce(new.id,'00000000-0000-0000-0000-000000000000'::uuid);
 if active_count >= 2 then raise exception 'A team may have at most two active HQ projects.' using errcode='23514'; end if;
 return new;
end; $$;
drop trigger if exists trg_team_hq_project_limit on public.caleris_team_hq_projects;
create trigger trg_team_hq_project_limit before insert or update of team_id,status on public.caleris_team_hq_projects for each row execute function public.enforce_team_hq_project_limit();